WFJ.Data.add("gossip", {
  ["8b0008a3a55b8c96"] = { "Vedo oltre il tuo travestimento, {race}. ⟦Number Two=Numero Due⟧! ⟦Number Two=Numero Due⟧, uccidi!", "." },
  ["8b08facbd5b421b4"] = { "È giunto il momento di rimettere le mie merci a disposizione di tutti coloro che passano vicino a ⟦Sentinel Hill=Guardiacolle⟧! Venite, venite tutti!", "." },
  ["8b0f0d5ba83cd210"] = { "Ho perso il mio ⟦Ring of the Gathering Storm=Anello della Tempesta Crescente⟧. Puoi sostituirmelo?", "." },
  ["8b20f109b420eb0e"] = { "Bethekk, la tua sacerdotessa invoca la tua potenza!", "." },
  ["8b24ae18e68ebd33"] = { "Ti do il benvenuto a Valanaar, {class}.", "." },
  ["8b24c8fec5658257"] = { "Un alleato vicino riporta in vita %s!", "." },
  ["8b252036937ff4d5"] = { "Salve, <straniero/straniera>, e <benvenuto/benvenuta> nella maestà selvaggia del ⟦Un'Goro Crater=Cratere di Un'Goro⟧!\n\nMi chiamo ⟦Williden Marshal=Williden Grant⟧. Mia sorella, i nostri compagni e io formiamo la Marshal Expeditions: scienziati ed esploratori del grande ignoto selvaggio di Azeroth.\n\nAbbiamo incontrato qualche difficoltà qui, e cerchiamo un po' d'aiuto, se hai tempo!", "." },
  ["8b2e9c8305029a7b"] = { "VanCleef manda a dire che i piani sono in corso. Ma ha sentito voci di qualcuno che ficca il naso in giro.", "." },
  ["8b2f0cd97e68d4a4"] = { "Calma, amico. Io addestro solo i guerrieri.", "." },
  ["8b370fcbb5c0ec36"] = { "Le nostre unità sono passate al grado di Veterano, ma non ho abbastanza rifornimenti per portarle a Campione.", "." },
  ["8b3771ba1fb00a74"] = { "Non troverai un maestro dei grifoni in un posto qualsiasi di Dun Morogh, <ragazzo/ragazza>. Dovrai andare a ⟦Ironforge=Forgiardente⟧ se vuoi prendere un grifone per andare da qualche parte.", "." },
  ["8b383acdc855dbe4"] = { "Bah, quella è roba da goblin! Comunque, qui a ⟦Razor Hill=Tranciacolle⟧ abbiamo un orco che ti insegnerà queste cose. Cerca Mukdrak vicino alla forgia.", "." },
  ["8b417d10ba024f23"] = { "Bestie schifose! Eccole che arrivano!", "." },
  ["8b4d8c148177d939"] = { "Avete qualche minuto per svegliarvi, ma cominciamo presto.", "." },
  ["8b51ea5bf502e7a1"] = { "Grazie, piccol<o/a> {race}!", "." },
  ["8b5fb0ef87f4f312"] = { "Ti stai divertendo?", "." },
  ["8b64575837f70f58"] = { "Bel lavoro, voi due. Ora andate a sedervi.", "." },
  ["8b6558700515da71"] = { "Dissoluzione dell'immagine tra sessanta secondi.", "." },
  ["8b7637dab55827b6"] = { "Evviva! La mia bambola!", "." },
  ["8b7d127f3ee11bb1"] = { "Dobbiamo sbrigarci.", "." },
  ["8b7f2078fedca5fb"] = { "Ce l'abbiamo fatta! Raggiungimi da Jer'kai, sopra l'accampamento dei Totem Truce.", "." },
  ["8b884d15f2365b9b"] = { "Fratello mio, no!", "." },
  ["8b8e352e7ce27002"] = { "Noi elfi abbiamo una lunga storia. Speriamo che questa storia non torni a perseguitarci.", "." },
  ["8b935cbcc4963949"] = { "Vorrei che fosse vero, {name}, ma per sconfiggere le forze di Razelikh e dei suoi subordinati non basterai tu soltanto.\n\nRiunisci un gruppo adeguato di avventurieri e aspiranti eroi e libera i miei uomini dalla loro eterna tortura! Diciotto pietre devi frantumare.\n\nCombatti con forza e muori con onore, {name}.", "." },
  ["8b97ce3a2cc4dcc0"] = { "E questo \"Signore del Vento\"? Al'Akir è reale, o un'invenzione del culto?", "." },
  ["8b99c393aa88ce9e"] = { "Sono un guaritore degli spiriti di prova.", "." },
  ["8b9e2c705c4ce07b"] = { "A quanto pare arrivi troppo tardi, {class}. Abbiamo tutto il raptor arrosto che ci serve: ucciso, cotto e salato. Comunque, sembra che qualcun altro qui intorno abbia bisogno di una mano. Dovresti andare a sentire loro. Io vado a vedere se adesso mi lasciano tornare a casa.", "." },
  ["8ba6030feea6990d"] = { "È ora di insegnarti un po' di buone maniere, <ragazzo/ragazza>.", "." },
  ["8ba7bea14ccae981"] = { "Davvero straordinario, Gerard. Come ci sei riuscito?", "." },
  ["8bb14995d052b45d"] = { "La fine è adesso, Fordring.", "." },
  ["8bb4c7fef87e4b39"] = { "Bene, ci siamo. Ci vorranno circa cinque minuti per spegnere questo affare con il rituale. Appena comincio, tienimi lontani i parassiti, o sarà la fine per tutti noi!", "." },
  ["8bb976d5eb7da308"] = { "Kazzak è supremo!", "." },
  ["8bbb25ff825e4a77"] = { "Anello interno di ⟦War Quarter=Quartiere della Guerra⟧, dove James Van Brunt lavora. Lui fa a noi buona maglia.", "." },
  ["8bbe20644ee7ea4b"] = { "Se Idraxis recluta altri per la sua guerra, l'equilibrio delle forze potrebbe cambiare...", "." },
  ["8bc4c2df69ba8d9b"] = { "Aiuto, aiuto! Mi stanno reprimendo!", "." },
  ["8bd1ac2684de6f31"] = { "La vostra vittoria avrà vita breve. I giorni sia dell'⟦Alliance=Alleanza⟧ sia dell'⟦Horde=Orda⟧ stanno per finire! La prossima volta che ci incontreremo sarà l'ultima.", "." },
  ["8bd3e0ddaa413561"] = { "È con Lyria che dovresti parlare se ti serve addestramento. Di solito la trovi dietro la fucina, in attesa che qualche armatura o arma sia finita.", "." },
  ["8bd3ef5fb87dbb0d"] = { "Bene, questo dovrebbe bastare. Su, torniamo alla bottega a concludere i nostri affari!", "." },
  ["8bd93c69b1470805"] = { "Dammi il travestimento da ogre viola!", "." },
  ["8bdeb3e2784d06fc"] = { "Non mostrate debolezza! Schiacciate queste creature immonde!", "." },
  ["8bdefb0540f81940"] = { "Ah... <un/una> cliente! Parla con la mia più grande invenzione, il ⟦Vendor-Tron 1000=Venditron 1000⟧. Ha tutto ciò che ti serve... alcuni degli oggetti più rari che troverai mai su qualsiasi mercato di Kalimdor... per non parlare del fatto che la sua programmazione non ammette alcuna contrattazione, quindi il prezzo che vedi è il prezzo che paghi.", "." },
  ["8be920b3fbb09c56"] = { "Chi ha disturbato l'altare della dea?", "." },
  ["8beb16a0ebce0dd2"] = { "%s chiama le sue guardie.", "." },
  ["8beccf5ad37e54d0"] = { "%s si infuria!", "." },
  ["8bf0848946292a7f"] = { "Allora, ora che il re sono io... cos'hai per me?!", "." },
  ["8bfaa0176f0913b9"] = { "Circa cinque mesi fa, la divisione di Rovotorto della S.P.R. & Co. mise le mani su un veleno speciale, ottenuto da un losco mercante di ⟦Booty Bay=Baia del Bottino⟧ di nome ⟦Crank Fizzlebub=Crank Raschiarullo⟧. A quanto pare Fizzlebub aveva rubato il veleno a Zanzil!\n\nSì, proprio ⟦Zanzil the Outcast=Zanzil l'Errante⟧, il troll esiliato dalla sua stessa tribù per la natura dei suoi \"esperimenti\" di negromanzia.\n\nNaturalmente, una volta avuto il veleno, lo provarono gli uni sugli altri. I risultati furono disastrosi.", "." },
  ["8bfaf189d3bef2ba"] = { "Sia i capitani dell'⟦Horde=Orda⟧ sia quelli dell'⟦Alliance=Alleanza⟧ sono scesi in campo. La nostra capitana Balinda Stonehearth dirige le forze dei Piccatonante dall'⟦Stonehearth Outpost=Avamposto di Cordipietra⟧, mentre il capitano nemico Galvangar abbaia ordini dall'interno del ⟦Iceblood Garrison=Presidio di Brinarossa⟧.\n\nAlla battaglia!", "." },
  ["8bfc2cd5e4a8a828"] = { "Il ⟦First Aid=Primo Soccorso⟧ è un'abilità preziosa. La nostra istruttrice, ⟦Nissa Firestone=Nissa Pietrardente⟧, può mostrarti come si fa. Cercala sul lato sud della ⟦Great Forge=Grande Forgia⟧, all'Ironforge Physician.", "." },
})
